function saveModels(string $path, array $items): bool { $json=json_encode(['items'=>array_values($items),'updatedAt'=>gmdate(DATE_ATOM)], JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT); if (!is_string($json)) return false; $tmp=$path.'.tmp-'.bin2hex(random_bytes(6)); if (file_put_contents($tmp,$json,LOCK_EX)===false) return false; @chmod($tmp,0600); if (!rename($tmp,$path)) { @unlink($tmp); return false; } @chmod($path,0600); return true; }
function requireAdmin(string $keyPath): void { if (!is_file($keyPath)) reply(503,['error'=>'Clé administrateur non configurée.']); $expected=trim((string)file_get_contents($keyPath)); $headers=function_exists('getallheaders')?getallheaders():[]; $provided=trim((string)($_SERVER['HTTP_X_MACUISINE_ADMIN_KEY']??'')); if ($provided==='' ) foreach($headers as $n=>$v) if(strcasecmp((string)$n,'X-Macuisine-Admin-Key')===0){$provided=trim((string)$v);break;} if($expected===''||$provided===''||!hash_equals($expected,$provided)) reply(401,['error'=>'Clé administrateur incorrecte.']); }
function cleanMeta(array $m): array { $id=trim((string)($m['id']??''));$hash=trim((string)($m['sha256']??''));$name=trim((string)($m['name']??''));if(!preg_match('/^model-[a-f0-9]{64}$/',$id)||!preg_match('/^[a-f0-9]{64}$/',$hash)||$id!=='model-'.$hash||$name===''||strlen($name)>256)reply(400,['error'=>'Identifiant ou nom de modèle invalide.']);$dims=[];foreach(['width','depth','height'] as $k){if(!isset($m[$k])||!is_numeric($m[$k])||(float)$m[$k]<=0||(float)$m[$k]>2000)reply(400,['error'=>'Dimensions incorrectes.']);$dims[$k]=(float)$m[$k];}return ['id'=>$id,'name'=>$name,'sha256'=>$hash,'byteLength'=>(int)($m['byteLength']??0),'width'=>$dims['width'],'depth'=>$dims['depth'],'height'=>$dims['height'],'sourceFilename'=>trim((string)($m['sourceFilename']??($name.'.glb')))]; }
$method=$_SERVER['REQUEST_METHOD']??'GET';$id=trim((string)($_GET['id']??''));
if($method==='GET') { $items=readModels($indexPath); if($id===''){header('Content-Type: application/json; charset=utf-8');echo json_encode(['items'=>$items],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;} if(!preg_match('/^model-[a-f0-9]{64}$/',$id))reply(400,['error'=>'Identifiant invalide.']);$item=null;foreach($items as $row)if(($row['id']??'')===$id){$item=$row;break;}if(!$item)reply(404,['error'=>'Modèle introuvable.']);$file=$modelDir.DIRECTORY_SEPARATOR.$id.'.glb';if(!is_file($file))reply(404,['error'=>'Fichier GLB introuvable.']);header('Content-Type: model/gltf-binary');header('Content-Length: '.filesize($file));header('Content-Disposition: attachment; filename="model.glb"');readfile($file);exit; }
requireAdmin($keyPath);
if($method==='POST') { if(!is_dir($modelDir)&&!mkdir($modelDir,0700,true)&&!is_dir($modelDir))reply(500,['error'=>'Impossible de créer le stockage des modèles.']);$file=$_FILES['file']??null;$meta=json_decode((string)($_POST['metadata']??''),true);if(!is_array($file)||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_array($meta))reply(400,['error'=>'Fichier GLB ou informations manquants.']);if(($file['size']??0)<20||($file['size']??0)>16*1024*1024)reply(413,['error'=>'Le fichier doit faire moins de 16 Mio.']);$bytes=file_get_contents((string)$file['tmp_name']);if(!is_string($bytes)||substr($bytes,0,4)!=="glTF")reply(400,['error'=>'Le fichier n’est pas un GLB valide.']);$hash=hash('sha256',$bytes);$meta['sha256']=$hash;$meta['id']='model-'.$hash;$meta['byteLength']=strlen($bytes);$clean=cleanMeta($meta);if(!isset($meta['sourceFilename'])||!preg_match('/.glb$/i',(string)$meta['sourceFilename']))$clean['sourceFilename']=$clean['name'].'.glb';$items=readModels($indexPath);foreach($items as $old)if(($old['id']??'')===$clean['id'])reply(409,['error'=>'Ce modèle est déjà dans le catalogue.']);$tmp=$modelDir.DIRECTORY_SEPARATOR.$clean['id'].'.tmp';if(file_put_contents($tmp,$bytes,LOCK_EX)===false)reply(500,['error'=>'Écriture du GLB impossible.']);@chmod($tmp,0600);if(!rename($tmp,$modelDir.DIRECTORY_SEPARATOR.$clean['id'].'.glb'))reply(500,['error'=>'Publication du GLB impossible.']);$items[]=$clean;if(!saveModels($indexPath,$items))reply(500,['error'=>'Enregistrement du catalogue impossible.']);reply(200,['item'=>$clean,'items'=>$items]); }
if($method==='PUT') { $payload=json_decode((string)file_get_contents('php://input'),true);if(!is_array($payload))reply(400,['error'=>'Données invalides.']);$id=trim((string)($payload['id']??''));$items=readModels($indexPath);$found=false;foreach($items as &$row){if(($row['id']??'')===$id){$payload['sha256']=$row['sha256'];$payload['byteLength']=$row['byteLength'];$payload['sourceFilename']=$row['sourceFilename'];$row=array_merge($row,cleanMeta($payload));$found=true;break;}}unset($row);if(!$found)reply(404,['error'=>'Modèle introuvable.']);if(!saveModels($indexPath,$items))reply(500,['error'=>'Enregistrement du catalogue impossible.']);reply(200,['items'=>$items]); }
if($method==='DELETE') { $payload=json_decode((string)file_get_contents('php://input'),true);$id=trim((string)($payload['id']??''));if(!preg_match('/^model-[a-f0-9]{64}$/',$id))reply(400,['error'=>'Identifiant invalide.']);$items=readModels($indexPath);$filtered=array_values(array_filter($items,fn($row)=>($row['id']??'')!==$id));if(count($filtered)===count($items))reply(404,['error'=>'Modèle introuvable.']);if(!saveModels($indexPath,$filtered))reply(500,['error'=>'Enregistrement du catalogue impossible.']);@unlink($modelDir.DIRECTORY_SEPARATOR.$id.'.glb');reply(200,['items'=>$filtered]); }
reply(405,['error'=>'Méthode non autorisée.']);
